import java.util.*;
import java.io.*;

public class DStress2_Variant2 {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        System.out.println(new DStress2_Variant2().calculate(s.toCharArray()));
        sc.close();
    }

    int INF = Integer.MAX_VALUE / 3;

    int calculate(char[] s) {
        List<Integer> vIndices = new ArrayList<>();
        List<Integer> kIndices = new ArrayList<>();
        List<Integer> otherIndices = new ArrayList<>();
        for (int i = 0; i < s.length; i++) {
            switch (s[i]) {
                case 'V': vIndices.add(i); break;
                case 'K': kIndices.add(i); break;
                default: otherIndices.add(i); break;
            }
        }
        int[][][][] dp = new int[2][vIndices.size() + 1][kIndices.size() + 1][otherIndices.size() + 1];
        for (int[][][] arr3 : dp)
            for (int[][] arr2 : arr3)
                for (int[] arr1 : arr2)
                    Arrays.fill(arr1, INF);
        dp[0][0][0][0] = 0;
        for (int vCount = 0; vCount <= vIndices.size(); vCount++) {
            for (int kCount = 0; kCount <= kIndices.size(); kCount++) {
                for (int oCount = 0; oCount <= otherIndices.size(); oCount++) {
                    for (int lastFlag = 0; lastFlag < 2; lastFlag++) {
                        int currentCost = dp[lastFlag][vCount][kCount][oCount];
                        if (currentCost == INF) continue;
                        if (vCount < vIndices.size()) {
                            int cost = currentCost + count(vIndices.get(vCount), kCount, kIndices) + count(vIndices.get(vCount), oCount, otherIndices);
                            dp[1][vCount + 1][kCount][oCount] = Math.min(dp[1][vCount + 1][kCount][oCount], cost);
                        }
                        if (kCount < kIndices.size() && lastFlag == 0) {
                            int cost = currentCost + count(kIndices.get(kCount), vCount, vIndices) + count(kIndices.get(kCount), oCount, otherIndices);
                            dp[0][vCount][kCount + 1][oCount] = Math.min(dp[0][vCount][kCount + 1][oCount], cost);
                        }
                        if (oCount < otherIndices.size()) {
                            int cost = currentCost + count(otherIndices.get(oCount), vCount, vIndices) + count(otherIndices.get(oCount), kCount, kIndices);
                            dp[0][vCount][kCount][oCount + 1] = Math.min(dp[0][vCount][kCount][oCount + 1], cost);
                        }
                    }
                }
            }
        }
        return Math.min(dp[0][vIndices.size()][kIndices.size()][otherIndices.size()], dp[1][vIndices.size()][kIndices.size()][otherIndices.size()]);
    }

    private int count(int position, int startIndex, List<Integer> list) {
        int count = 0;
        for (int i = startIndex; i < list.size(); i++) {
            if (list.get(i) < position) count++;
        }
        return count;
    }
}
