def calculate(s):
    v_indices = []
    k_indices = []
    other_indices = []

    for i, ch in enumerate(s):
        if ch == 'V':
            v_indices.append(i)
        elif ch == 'K':
            k_indices.append(i)
        else:
            other_indices.append(i)

    INF = float('inf') / 3
    v_len = len(v_indices)
    k_len = len(k_indices)
    o_len = len(other_indices)

    # Initialize 4D DP array
    dp = [[[[INF for _ in range(o_len + 1)] for _ in range(k_len + 1)] for _ in range(v_len + 1)] for _ in range(2)]
    dp[0][0][0][0] = 0

    def count(pos, start_idx, lst):
        cnt = 0
        for i in range(start_idx, len(lst)):
            if lst[i] < pos:
                cnt += 1
        return cnt

    for v_count in range(v_len + 1):
        for k_count in range(k_len + 1):
            for o_count in range(o_len + 1):
                for last_flag in range(2):
                    current_cost = dp[last_flag][v_count][k_count][o_count]
                    if current_cost == INF:
                        continue
                    # Add V
                    if v_count < v_len:
                        cost = current_cost + count(v_indices[v_count], k_count, k_indices) + count(v_indices[v_count], o_count, other_indices)
                        if cost < dp[1][v_count + 1][k_count][o_count]:
                            dp[1][v_count + 1][k_count][o_count] = cost
                    # Add K
                    if k_count < k_len and last_flag == 0:
                        cost = current_cost + count(k_indices[k_count], v_count, v_indices) + count(k_indices[k_count], o_count, other_indices)
                        if cost < dp[0][v_count][k_count + 1][o_count]:
                            dp[0][v_count][k_count + 1][o_count] = cost
                    # Add other
                    if o_count < o_len:
                        cost = current_cost + count(other_indices[o_count], v_count, v_indices) + count(other_indices[o_count], k_count, k_indices)
                        if cost < dp[0][v_count][k_count][o_count + 1]:
                            dp[0][v_count][k_count][o_count + 1] = cost

    return int(min(dp[0][v_len][k_len][o_len], dp[1][v_len][k_len][o_len]))

